import torch, time, statistics as st
import b200probe as bp
from sol_execbench.core.bench import timing
SRC = r'''
__device__ __forceinline__ float silu_bw(float g, float x, float s) {
    return __fmul_rn(g, __fmul_rn(s, __fadd_rn(1.0f, __fmul_rn(x, __fsub_rn(1.0f, s)))));
}
__device__ __forceinline__ float4 ld4h(const float* p, unsigned long long pol){float4 v;
 asm volatile("ld.global.L2::cache_hint.v4.f32 {%0,%1,%2,%3}, [%4], %5;":"=f"(v.x),"=f"(v.y),"=f"(v.z),"=f"(v.w):"l"(p),"l"(pol)); return v;}
__device__ __forceinline__ void st4h(float* p, float4 v, unsigned long long pol){
 asm volatile("st.global.L2::cache_hint.v4.f32 [%0], {%1,%2,%3,%4}, %5;"::"l"(p),"f"(v.x),"f"(v.y),"f"(v.z),"f"(v.w),"l"(pol):"memory");}
extern "C" __global__ void __launch_bounds__(256) r0(const float* g,const float* x,const float* s,float* o,long long n){
 long long i=(long long)blockIdx.x*256+threadIdx.x; if(i<(n>>2)){
 unsigned long long pl,ps; asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;":"=l"(pl));
 asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;":"=l"(ps));
 float4 a=ld4h(g+4*i,pl),b=ld4h(x+4*i,pl),c=ld4h(s+4*i,pl),r;
 r.x=silu_bw(a.x,b.x,c.x);r.y=silu_bw(a.y,b.y,c.y);r.z=silu_bw(a.z,b.z,c.z);r.w=silu_bw(a.w,b.w,c.w); st4h(o+4*i,r,ps);}}
extern "C" __global__ void __launch_bounds__(256) rdonly(const float* g,const float* x,const float* s,float* o,long long n){
 long long i=(long long)blockIdx.x*256+threadIdx.x; float acc=0.f; if(i<(n>>2)){
 unsigned long long pl; asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;":"=l"(pl));
 float4 a=ld4h(g+4*i,pl),b=ld4h(x+4*i,pl),c=ld4h(s+4*i,pl);
 acc=silu_bw(a.x,b.x,c.x)+silu_bw(a.y,b.y,c.y)+silu_bw(a.z,b.z,c.z)+silu_bw(a.w,b.w,c.w);}
 if(acc==12345.678f) o[i]=acc; }
extern "C" __global__ void __launch_bounds__(256) wronly(const float* g,const float* x,const float* s,float* o,long long n){
 long long i=(long long)blockIdx.x*256+threadIdx.x; if(i<(n>>2)){
 unsigned long long ps; asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;":"=l"(ps));
 float4 r=make_float4(1.f,2.f,3.f,(float)i); st4h(o+4*i,r,ps);}}
extern "C" __global__ void sweep(const float4* p,long long n4,float* out){
 long long i=(long long)blockIdx.x*blockDim.x+threadIdx.x; float acc=0.f;
 for(;i<n4;i+=(long long)gridDim.x*blockDim.x){float4 v=p[i]; acc+=v.x+v.y+v.z+v.w;}
 if(acc==12345.678f) out[0]=acc;}
'''
K={n:bp.cuda_kernel(SRC,n) for n in ['r0','rdonly','wronly','sweep']}
L2=torch.cuda.get_device_properties(0).L2_cache_size*2
buf2=torch.empty(L2//4,dtype=torch.float32,device='cuda')
sink=torch.empty(1,device='cuda')
def sweep(b):
    K['sweep']((148*8,),(256,),b,b.numel()//4,sink)
orig=timing._clear_cache
flushes={'dirty':orig,'clean':lambda c: sweep(buf2),'zero+sweep':lambda c:(c.zero_(),sweep(buf2))}
sizes=[163840,786432,2097152,8388608,16777216]
res={}
import sys
t0=time.time()
for rep in range(3):
  for n in sizes:
    g,x,s=[torch.randn(n,device='cuda') for _ in range(3)]; o=torch.empty(n,device='cuda')
    grid=((n//4+255)//256,)
    for kn in ['r0','rdonly','wronly']:
      fn=lambda a,b,c,d,kn=kn,grid=grid: K[kn](grid,(256,),a,b,c,d,n)
      for fl,f in flushes.items():
        timing._clear_cache=f
        t=bp.harness_time(fn,[g,x,s],[o],warmup=5,rep=25)
        res.setdefault((n,kn,fl),[]).append(t)
  if time.time()-t0>80: break
timing._clear_cache=orig
print('reps',rep+1, 'time',time.time()-t0)
for n in sizes:
  for kn in ['r0','rdonly','wronly']:
    print(n*16/1e6, kn, ' '.join(f"{fl}:{st.median(res[(n,kn,fl)]):.2f}" for fl in flushes))

