__device__ __forceinline__ float4 ld4h(const float* p, unsigned long long pol){float4 v;
 asm volatile("ld.global.L2::cache_hint.v4.f32 {%0,%1,%2,%3}, [%4], %5;":"=f"(v.x),"=f"(v.y),"=f"(v.z),"=f"(v.w):"l"(p),"l"(pol)); return v;}
__device__ __forceinline__ void st4h(float* p, float4 v, unsigned long long pol){
 asm volatile("st.global.L2::cache_hint.v4.f32 [%0], {%1,%2,%3,%4}, %5;"::"l"(p),"f"(v.x),"f"(v.y),"f"(v.z),"f"(v.w),"l"(pol):"memory");}
__device__ __forceinline__ float4 f4(float4 a,float4 b,float4 c){float4 r;
 r.x=silu_bw(a.x,b.x,c.x);r.y=silu_bw(a.y,b.y,c.y);r.z=silu_bw(a.z,b.z,c.z);r.w=silu_bw(a.w,b.w,c.w);return r;}
